struct BoxTextVTable {
    char padding0[80];
    short changeScale_adjustment;
    short changeScale_reserved;
    void (*changeScale_function)(void *, float);
    short changePos_adjustment;
    short changePos_reserved;
    void (*changePos_function)(void *, float, float);
};

class BoxText {
    char padding0[76];
    BoxTextVTable *vtable;

public:
    void changeScale(float scale)
    {
        vtable->changeScale_function(
            (char *)this + vtable->changeScale_adjustment,
            scale
        );
    }

    void changePos(float x, float y)
    {
        vtable->changePos_function(
            (char *)this + vtable->changePos_adjustment,
            x,
            y
        );
    }

    int makeBox(int width, int height, bool reverse = false,
                float scale_override = -1, int height_override = -1);
};

