class GoalsMenuClass {
    char padding0[124];
    BoxText *names[5];
    TextString *status[5];

public:
    void SetNoTip();
};

__asm__(".equ makeBox__7BoxTextiibfi, 0x00149D30");

void GoalsMenuClass::SetNoTip()
{
	static const int spacing = 50;
	static const int extra_spacing = 20;
	int extra_lines = 0;
	float scale = 1.0f;

	for(int i=0; i<5; i++)
	{
		int y = 105 + (i*spacing) + extra_lines*extra_spacing;
		names[i]->changePos(320, y);
		names[i]->changeScale(scale);
		extra_lines += names[i]->makeBox(502, 200) - 1;
		y = 105 + (i*spacing) + (extra_lines+1)*extra_spacing;
		status[i]->changePos(320, y);
		status[i]->changeScale(scale);
	}
}
